<?php
require_once __DIR__.'/../../../app/bootstrap.php';require_once __DIR__.'/../../../app/Modules/Marketplace/Marketplace.php';Auth::requirePermission('transactions.view');
$pageTitle='Layanan Marketplace';$db=Database::connect();marketplace_install($db);marketplace_service_install($db);
$status=trim((string)($_GET['status']??''));$type=trim((string)($_GET['type']??''));$q=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$per=25;$where=[];$params=[];
if($status!==''){$where[]='c.status=?';$params[]=$status;}if($type!==''){$where[]='c.case_type=?';$params[]=$type;}if($q!==''){$where[]='(c.case_number LIKE ? OR o.order_number LIKE ? OR cu.name LIKE ? OR cu.phone LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);} $ws=$where?'WHERE '.implode(' AND ',$where):'';
$ct=$db->prepare("SELECT COUNT(*) FROM marketplace_service_cases c JOIN online_orders o ON o.id=c.order_id JOIN customers cu ON cu.id=c.customer_id {$ws}");$ct->execute($params);$total=(int)$ct->fetchColumn();$pages=max(1,(int)ceil($total/$per));$off=($page-1)*$per;
$st=$db->prepare("SELECT c.*,o.order_number,cu.name customer_name,cu.phone customer_phone FROM marketplace_service_cases c JOIN online_orders o ON o.id=c.order_id JOIN customers cu ON cu.id=c.customer_id {$ws} ORDER BY c.id DESC LIMIT {$per} OFFSET {$off}");$st->execute($params);$rows=$st->fetchAll()?:[];
require_once __DIR__.'/../../layouts/admin-header.php';require_once __DIR__.'/../../layouts/admin-sidebar.php';
?>
<link rel="stylesheet" href="<?=legacy_base_url('assets/css/system.css?v=14.0.0')?>"><style>.case-filters{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:10px}.case-filters input,.case-filters select{width:100%;padding:11px;border:1px solid #dbe3ee;border-radius:12px}.case-badge{padding:5px 9px;border-radius:999px;background:#f1f5f9;font-size:12px;font-weight:800}.case-badge.waiting_admin{background:#fef3c7;color:#92400e}.case-badge.approved,.case-badge.resolved{background:#dcfce7;color:#166534}.case-badge.rejected,.case-badge.closed{background:#fee2e2;color:#991b1b}.pager{display:flex;gap:6px;margin-top:14px;flex-wrap:wrap}.pager a{padding:8px 11px;border:1px solid #e2e8f0;border-radius:9px;text-decoration:none}.pager a.active{background:#111827;color:#fff}@media(max-width:850px){.case-filters{grid-template-columns:1fr}.system-table-wrap{overflow:auto}}</style>
<main class="admin-main system-wrap"><header class="admin-topbar page-topbar"><button class="sidebar-toggle" id="sidebarToggle"><i class="bi bi-list"></i></button><div class="topbar-title"><h1>Layanan Marketplace</h1><p>Pembatalan, komplain, retur/refund, dan percakapan pelanggan.</p></div></header><section class="system-form-card"><form class="case-filters"><input name="q" value="<?=e($q)?>" placeholder="Cari kasus / order / pelanggan"><select name="type"><option value="">Semua Jenis</option><?php foreach(['cancel_refund','return_refund','complaint','support'] as $x):?><option value="<?=e($x)?>" <?=$type===$x?'selected':''?>><?=e(marketplace_service_type_label($x))?></option><?php endforeach;?></select><select name="status"><option value="">Semua Status</option><?php foreach(['waiting_admin','waiting_customer','approved','rejected','resolved','closed'] as $x):?><option value="<?=e($x)?>" <?=$status===$x?'selected':''?>><?=e(marketplace_service_status_label($x))?></option><?php endforeach;?></select><button class="system-btn primary"><i class="bi bi-search"></i> Filter</button></form><div class="system-table-wrap" style="margin-top:16px"><table class="system-table"><thead><tr><th>Kasus</th><th>Pesanan</th><th>Pelanggan</th><th>Jenis</th><th>Refund</th><th>Status</th><th>Waktu</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" style="text-align:center;padding:28px">Belum ada pengajuan.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=e($r['case_number'])?></b><br><small><?=e($r['reason']?:'-')?></small></td><td><?=e($r['order_number'])?></td><td><b><?=e($r['customer_name'])?></b><br><small><?=e($r['customer_phone']?:'-')?></small></td><td><?=e(marketplace_service_type_label((string)$r['case_type']))?></td><td><?=e(strtoupper((string)$r['refund_status']))?><?php if((float)$r['refund_amount']>0):?><br><small><?=rupiah($r['refund_amount'])?></small><?php endif;?></td><td><span class="case-badge <?=e($r['status'])?>"><?=e(marketplace_service_status_label((string)$r['status']))?></span></td><td><?=e(date('d/m/Y H:i',strtotime((string)$r['created_at'])))?></td><td><a class="system-btn soft" href="<?=legacy_base_url('admin/marketplace-service/detail.php?id='.(int)$r['id'])?>">Detail</a></td></tr><?php endforeach;?></tbody></table></div><?php if($pages>1):?><div class="pager"><?php for($i=1;$i<=$pages;$i++):?><a class="<?=$i===$page?'active':''?>" href="?<?=http_build_query(['q'=>$q,'type'=>$type,'status'=>$status,'page'=>$i])?>"><?=$i?></a><?php endfor;?></div><?php endif;?></section></main>
